CREATE OR REPLACE FUNCTION public.kinojo_log_page_view(p_page_key text DEFAULT NULL::text, p_page_url text DEFAULT NULL::text, p_visitor_key text DEFAULT NULL::text, p_referrer text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_source_type text DEFAULT 'WEB'::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text:=gen_random_uuid()::text; v_key text; v_event text; v_pass text; v_member public.member_codes%rowtype; v_date date:=(now() at time zone 'Asia/Seoul')::date; v_payload jsonb; v_has_member boolean:=false;
begin
 v_key:=public.kinojo_visit_page_key_266(p_page_key,p_page_url);
 v_event:=case when upper(coalesce(p_payload->>'eventType','PAGE_VIEW'))='LOGIN' then 'LOGIN' else 'PAGE_VIEW' end;
 v_pass:=public.kinojo_normalize_pass_key(coalesce(p_payload->>'authPassKey',p_payload->>'passKey',p_payload->>'passCode',''));
 v_payload:=coalesce(p_payload,'{}'::jsonb)-'authPassKey'-'passKey'-'passCode';
 if v_pass<>'' then
   select * into v_member from public.member_codes where public.kinojo_normalize_pass_key(pass_code)=v_pass and is_active is true limit 1;
   v_has_member:=found;
 end if;
 insert into public.kinojo_page_view_events(event_id,page_key,page_url,visitor_key,referrer,user_agent,source_type,payload,event_type,member_id,member_name,member_role,visit_date_kst)
 values(v_id,v_key,left(coalesce(p_page_url,''),1000),left(coalesce(p_visitor_key,''),160),left(coalesce(p_referrer,''),1000),left(coalesce(p_user_agent,''),500),coalesce(nullif(trim(p_source_type),''),'WEB'),v_payload,v_event,
   case when v_has_member then v_member.id else null end,case when v_has_member then v_member.main_character_name else null end,
   case when v_has_member then public.kinojo_normalize_role(v_member.role,v_member.level) else null end,v_date);
 if v_has_member and v_event='LOGIN' then update public.member_codes set last_login_at=now() where id=v_member.id; end if;
 perform public.kinojo_refresh_visit_daily_266(v_date);
 perform public.kinojo_run_visit_maintenance_266();
 return jsonb_build_object('ok',true,'eventId',v_id,'pageKey',v_key,'eventType',v_event);
end $function$

CREATE OR REPLACE FUNCTION public.kinojo_log_page_view_v329(p_page_key text DEFAULT NULL::text, p_page_url text DEFAULT NULL::text, p_visitor_key text DEFAULT NULL::text, p_referrer text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_source_type text DEFAULT 'WEB'::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
  v_credential text := btrim(coalesce(v_payload->>'authCredential',v_payload->>'authPassKey',v_payload->>'passKey',v_payload->>'passCode',''));
  v_member public.member_codes%rowtype;
begin
  v_payload := v_payload - 'authCredential' - 'authPassKey' - 'passKey' - 'passCode';
  if v_credential <> '' then
    select * into v_member
    from public.kinojo_member_from_web_credential_v326(v_credential)
    limit 1;
    if found then
      v_payload := v_payload || jsonb_build_object('authPassKey',v_member.pass_code);
    end if;
  end if;
  return public.kinojo_log_page_view(
    p_page_key,p_page_url,p_visitor_key,p_referrer,p_user_agent,p_source_type,v_payload
  );
end;
$function$
